<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { AlertOctagon, CheckCheck, Plus, RefreshCw, Search, Siren } from 'lucide-vue-next';
import { ElMessage, ElMessageBox } from 'element-plus';
import gsap from 'gsap';
import { api } from '../api';
import PageHeader from '../components/PageHeader.vue';
import { useSessionStore } from '../stores/session';
import type { PageData } from '../types';

const session=useSessionStore(),route=useRoute(),router=useRouter(),root=ref<HTMLElement|null>(null),loading=ref(false),error=ref(''),rows=ref<any[]>([]),total=ref(0),page=ref(1),q=ref(String(route.query.q??'')),level=ref(String(route.query.level??'')),status=ref(String(route.query.status??'')),type=ref(String(route.query.type??'')),enterpriseId=ref(String(route.query.enterpriseId??'')),selected=ref<any[]>([]),drawer=ref(false),detail=ref<any>(null),detailLoading=ref(false),createDialog=ref(false),saving=ref(false),taskDialog=ref(false),taskAlert=ref<any>(null);const options=reactive<any>({vehicles:[],enterprises:[],organizations:[],assignees:[]});const summary=reactive({pendingConfirmation:0,pendingHandling:0,inProgress:0,pendingReview:0,closed:0,critical:0});const isEnterprise=computed(()=>session.user?.portal==='ENTERPRISE');const canHandle=computed(()=>session.user?.permissions.includes('safety:alert:handle'));const canCreate=computed(()=>session.user?.permissions.includes('safety:alert:write'));const canDispatch=computed(()=>session.user?.permissions.includes('safety:emergency:dispatch'));const form=reactive({vehicleId:'',alertType:'MANUAL_REPORT',level:'MEDIUM',title:'',description:'',address:'',occurredAt:''});const taskForm=reactive({title:'',requirement:'',assigneeUserId:'',responseMode:'REMOTE',dueAt:''});let timer:number|undefined;
const statusText=(v:string)=>({PENDING_CONFIRMATION:'待确认',PENDING_HANDLING:'待处置',IN_PROGRESS:'处理中',PENDING_REVIEW:'待复核',CLOSED:'已关闭'}as any)[v]??v;const levelText=(v:string)=>({LOW:'低',MEDIUM:'中',HIGH:'高',CRITICAL:'重大'}as any)[v]??v;const typeText=(v:string)=>({VEHICLE_FAULT:'车辆故障',AUTONOMOUS_ABNORMAL:'自动驾驶异常',SYSTEM_ABNORMAL:'系统异常',OVERSPEED:'超速',OUT_OF_BOUNDS:'越界',NO_ENTRY:'禁行区',OFFLINE:'离线',DEVICE_ABNORMAL:'设备异常',SENSOR_ABNORMAL:'传感器异常',MANUAL_REPORT:'人工上报',OTHER:'其他风险'}as any)[v]??v;const fmt=(v:string)=>new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
async function loadOptions(){Object.assign(options,await api<any>('/safety/options'));if(!form.vehicleId)form.vehicleId=options.vehicles[0]?.id??''}
async function load(){loading.value=true;error.value='';try{const p=new URLSearchParams({page:String(page.value),pageSize:'20'});for(const [k,v] of Object.entries({q:q.value,level:level.value,status:status.value,type:type.value,enterpriseId:enterpriseId.value}))if(v)p.set(k,v);const data=await api<any>(`/safety/alerts?${p}`);rows.value=data.items;total.value=data.total;Object.assign(summary,data.summary);await router.replace({query:Object.fromEntries([...p.entries()].filter(([k])=>!['page','pageSize'].includes(k)))})}catch(reason){error.value=reason instanceof Error?reason.message:'告警加载失败'}finally{loading.value=false}}
watch([q,level,status,type,enterpriseId],()=>{page.value=1;clearTimeout(timer);timer=window.setTimeout(load,180)});watch(page,load);let motion:ReturnType<typeof gsap.matchMedia>|undefined;onMounted(async()=>{await Promise.all([load(),loadOptions()]);await nextTick();motion=gsap.matchMedia();motion.add('(prefers-reduced-motion: no-preference)',()=>{const context=gsap.context(()=>gsap.from('.safety-metrics > button',{y:8,opacity:0,duration:.32,stagger:.045,ease:'power2.out'}),root.value??undefined);return()=>context.revert()})});onUnmounted(()=>{clearTimeout(timer);motion?.revert()});
async function open(row:any){drawer.value=true;detailLoading.value=true;try{detail.value=await api<any>(`/safety/alerts/${row.id}`)}finally{detailLoading.value=false}}
function nextAction(row:any){if(row.status==='PENDING_CONFIRMATION'&&canHandle.value)return['CONFIRM','确认告警'];if(row.status==='PENDING_HANDLING'&&canHandle.value)return['START','开始处置'];if(row.status==='IN_PROGRESS')return['SUBMIT_REVIEW','提交复核'];if(row.status==='PENDING_REVIEW'&&canHandle.value)return['CLOSE','复核关闭'];return null}
async function act(row:any,action?:string){const resolved=action??nextAction(row)?.[0];if(!resolved)return;let comment='';try{const result=await ElMessageBox.prompt('填写本次处理意见，内容将进入审计记录。',nextAction(row)?.[1]??'批量处理',{confirmButtonText:'确认',cancelButtonText:'取消',inputType:'textarea',inputValidator:(v:string)=>v?.trim()?true:'请输入处理意见'});comment=result.value}catch{return}await api(`/safety/alerts/${row.id}/actions`,{method:'POST',body:JSON.stringify({action:resolved,comment})});ElMessage.success(`${nextAction(row)?.[1]??'处理'}成功`);if(detail.value?.id===row.id)detail.value=await api<any>(`/safety/alerts/${row.id}`);await load()}
async function bulkConfirm(){const targets=selected.value.filter(item=>item.status==='PENDING_CONFIRMATION');if(!targets.length)return ElMessage.warning('所选告警中没有待确认记录');await ElMessageBox.confirm(`确认批量处理 ${targets.length} 条待确认告警？`,'批量确认',{type:'warning'});await Promise.all(targets.map(item=>api(`/safety/alerts/${item.id}/actions`,{method:'POST',body:JSON.stringify({action:'CONFIRM',comment:'批量确认并进入待处置队列'})})));ElMessage.success(`已确认 ${targets.length} 条告警`);selected.value=[];await load()}
function openCreate(){Object.assign(form,{vehicleId:options.vehicles[0]?.id??'',alertType:'MANUAL_REPORT',level:'MEDIUM',title:'',description:'',address:'',occurredAt:new Date().toISOString().slice(0,16)});createDialog.value=true}
async function create(){if(!form.vehicleId||!form.title||!form.description)return ElMessage.warning('请选择车辆并填写标题和事件说明');saving.value=true;try{await api('/safety/alerts',{method:'POST',body:JSON.stringify({...form,occurredAt:new Date(form.occurredAt).toISOString()})});ElMessage.success('安全事件已上报并进入告警中心');createDialog.value=false;await load()}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'上报失败')}finally{saving.value=false}}
function openTask(row:any){taskAlert.value=row;Object.assign(taskForm,{title:`${row.title}处置任务`,requirement:'请立即核实现场情况，按时反馈处置经过、结果和整改措施。',assigneeUserId:options.assignees[0]?.id??'',responseMode:'REMOTE',dueAt:new Date(Date.now()+4*3600000).toISOString().slice(0,16)});taskDialog.value=true}
async function createTask(){if(!taskForm.title.trim()||!taskForm.requirement.trim()||!taskForm.dueAt)return ElMessage.warning('请填写任务标题、处置要求和时限');saving.value=true;try{await api('/safety/emergency-tasks',{method:'POST',body:JSON.stringify({...taskForm,alertId:taskAlert.value.id,dueAt:new Date(taskForm.dueAt).toISOString()})});ElMessage.success('应急处置任务已生成');taskDialog.value=false;await load()}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'任务创建失败')}finally{saving.value=false}}
</script>
<template><section ref="root"><PageHeader :title="isEnterprise?'我的告警':'告警中心'" :description="isEnterprise?'核实并处置本企业安全告警，提交监管复核。':'统一归集主动上报、规则识别、围栏和离线风险，按责任闭环处置。'" :count="total"><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button><el-button v-if="canCreate" type="primary" :icon="Plus" @click="openCreate">上报事件</el-button></PageHeader><div class="safety-metrics" aria-label="告警处置概况"><button @click="status='PENDING_CONFIRMATION'"><span>待确认</span><strong>{{summary.pendingConfirmation}}</strong><small>需要判定是否成立</small></button><button @click="status='PENDING_HANDLING'"><span>待处置</span><strong>{{summary.pendingHandling}}</strong><small>已确认，尚未接手</small></button><button @click="status='IN_PROGRESS'"><span>处理中</span><strong>{{summary.inProgress}}</strong><small>责任人正在处理</small></button><button @click="status='PENDING_REVIEW'"><span>待复核</span><strong>{{summary.pendingReview}}</strong><small>等待监管结论</small></button><button class="critical" @click="level='CRITICAL';status='' "><AlertOctagon :size="17"/><span>重大未关闭</span><strong>{{summary.critical}}</strong><small>优先进入应急处置</small></button></div><div class="table-toolbar safety-toolbar"><el-input v-model="q" :prefix-icon="Search" clearable placeholder="搜索告警编号、标题、车辆" aria-label="搜索告警"/><el-select v-model="type" clearable placeholder="全部类型"><el-option v-for="item in ['VEHICLE_FAULT','AUTONOMOUS_ABNORMAL','OVERSPEED','OUT_OF_BOUNDS','NO_ENTRY','OFFLINE','MANUAL_REPORT']" :key="item" :label="typeText(item)" :value="item"/></el-select><el-select v-model="level" clearable placeholder="全部等级"><el-option v-for="item in ['CRITICAL','HIGH','MEDIUM','LOW']" :key="item" :label="`${levelText(item)}风险`" :value="item"/></el-select><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="item in ['PENDING_CONFIRMATION','PENDING_HANDLING','IN_PROGRESS','PENDING_REVIEW','CLOSED']" :key="item" :label="statusText(item)" :value="item"/></el-select><el-select v-if="!isEnterprise" v-model="enterpriseId" clearable filterable placeholder="全部企业"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select></div><div v-if="selected.length&&canHandle" class="bulk-bar"><span><CheckCheck :size="15"/>已选择 {{selected.length}} 条</span><el-button size="small" @click="bulkConfirm">批量确认待确认告警</el-button></div><div v-if="error" class="error-state"><strong>告警中心暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><template v-else><el-table v-loading="loading" :data="rows" row-key="id" empty-text="暂无符合条件的告警" @selection-change="selected=$event"><el-table-column type="selection" width="42"/><el-table-column label="告警" min-width="245"><template #default="{row}"><button class="table-link" @click="open(row)"><strong>{{row.title}}</strong><span>{{row.businessNo}} · {{typeText(row.alertType)}}</span></button></template></el-table-column><el-table-column label="等级" width="84"><template #default="{row}"><span class="risk-level" :class="row.level.toLowerCase()"><i></i>{{levelText(row.level)}}</span></template></el-table-column><el-table-column label="车辆" min-width="150"><template #default="{row}"><div class="identity-cell"><strong>{{row.vehicle?.name||'平台事件'}}</strong><span>{{row.vehicle?.businessNo||row.source}}</span></div></template></el-table-column><el-table-column v-if="!isEnterprise" label="企业 / 机构" min-width="210"><template #default="{row}"><div class="identity-cell"><strong>{{row.enterprise.name}}</strong><span>{{row.organization.name}}</span></div></template></el-table-column><el-table-column label="发生时间" width="142"><template #default="{row}">{{fmt(row.occurredAt)}}</template></el-table-column><el-table-column label="状态 / 负责人" min-width="128"><template #default="{row}"><div class="identity-cell"><el-tag size="small" :type="row.status==='CLOSED'?'success':row.status==='PENDING_REVIEW'?'warning':row.level==='CRITICAL'?'danger':'primary'">{{statusText(row.status)}}</el-tag><span>{{row.responsibleUser?.displayName||'待认领'}}</span></div></template></el-table-column><el-table-column label="操作" width="132" fixed="right"><template #default="{row}"><el-button v-if="nextAction(row)" link type="primary" @click="act(row)">{{nextAction(row)?.[1]}}</el-button><el-dropdown><el-button link aria-label="更多操作">更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="open(row)">查看详情</el-dropdown-item><el-dropdown-item v-if="canDispatch&&row.status!=='CLOSED'" @click="openTask(row)">生成处置任务</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table><div class="pagination-row"><span>当前显示 {{rows.length}} / {{total}}</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next"/></div></template>
<el-drawer v-model="drawer" size="760px" destroy-on-close><template #header><div class="archive-drawer-title"><div><span>{{detail?.businessNo}}</span><h2>告警处置详情</h2></div><el-tag v-if="detail">{{statusText(detail.status)}}</el-tag></div></template><div v-loading="detailLoading"><template v-if="detail"><div class="case-hero" :class="detail.level.toLowerCase()"><Siren :size="22"/><div><span>{{typeText(detail.alertType)}} · {{levelText(detail.level)}}风险</span><strong>{{detail.title}}</strong><small>{{fmt(detail.occurredAt)}} · {{detail.source}}</small></div></div><dl class="detail-grid"><div><dt>所属企业</dt><dd>{{detail.enterprise.name}}</dd></div><div><dt>关联车辆</dt><dd>{{detail.vehicle?.name||'—'}}</dd></div><div><dt>事发位置</dt><dd>{{detail.address||`${detail.longitude??'—'}, ${detail.latitude??'—'}`}}</dd></div><div><dt>责任人</dt><dd>{{detail.responsibleUser?.displayName||'待认领'}}</dd></div><div class="detail-span-2"><dt>事件说明</dt><dd>{{detail.description||'—'}}</dd></div><div class="detail-span-2"><dt>最近处理意见</dt><dd>{{detail.lastComment||'尚无处理意见'}}</dd></div></dl><div class="related-strip"><span>围栏触发 {{detail.fenceTrigger?1:0}}</span><span>离线事件 {{detail.offlineEvent?1:0}}</span><span>事故 {{detail.accidents.length}}</span><span>违规 {{detail.violations.length}}</span><span>处置任务 {{detail.emergencyTasks.length}}</span></div><div class="drawer-actions"><el-button v-if="canDispatch&&detail.status!=='CLOSED'" @click="openTask(detail)">生成处置任务</el-button><el-button v-if="nextAction(detail)" type="primary" @click="act(detail)">{{nextAction(detail)?.[1]}}</el-button></div></template></div></el-drawer>
<el-dialog v-model="createDialog" title="上报安全事件" width="680px"><div class="form-grid"><el-form-item label="涉及车辆" required><el-select v-model="form.vehicleId" filterable><el-option v-for="item in options.vehicles" :key="item.id" :label="`${item.name} · ${item.businessNo}`" :value="item.id"/></el-select></el-form-item><el-form-item label="事件类型"><el-select v-model="form.alertType"><el-option v-for="item in ['VEHICLE_FAULT','AUTONOMOUS_ABNORMAL','SYSTEM_ABNORMAL','DEVICE_ABNORMAL','SENSOR_ABNORMAL','MANUAL_REPORT','OTHER']" :key="item" :label="typeText(item)" :value="item"/></el-select></el-form-item><el-form-item label="风险等级"><el-select v-model="form.level"><el-option v-for="item in ['LOW','MEDIUM','HIGH','CRITICAL']" :key="item" :label="levelText(item)" :value="item"/></el-select></el-form-item><el-form-item label="发生时间"><el-date-picker v-model="form.occurredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item class="form-span-2" label="事件标题" required><el-input v-model.trim="form.title"/></el-form-item><el-form-item class="form-span-2" label="事件说明" required><el-input v-model.trim="form.description" type="textarea" :rows="4"/></el-form-item><el-form-item class="form-span-2" label="位置描述"><el-input v-model.trim="form.address"/></el-form-item></div><template #footer><el-button @click="createDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">确认上报</el-button></template></el-dialog>
<el-dialog v-model="taskDialog" title="生成应急处置任务" width="660px"><p class="dialog-note">来源：{{taskAlert?.businessNo}} · {{taskAlert?.title}}</p><div class="form-grid"><el-form-item class="form-span-2" label="任务标题" required><el-input v-model.trim="taskForm.title"/></el-form-item><el-form-item label="责任人"><el-select v-model="taskForm.assigneeUserId" filterable><el-option v-for="item in options.assignees" :key="item.id" :label="item.displayName" :value="item.id"/></el-select></el-form-item><el-form-item label="处置方式"><el-select v-model="taskForm.responseMode"><el-option label="远程处置" value="REMOTE"/><el-option label="现场处置" value="FIELD"/></el-select></el-form-item><el-form-item class="form-span-2" label="处置时限" required><el-date-picker v-model="taskForm.dueAt" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item class="form-span-2" label="处置要求" required><el-input v-model.trim="taskForm.requirement" type="textarea" :rows="4"/></el-form-item></div><template #footer><el-button @click="taskDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="createTask">生成任务</el-button></template></el-dialog></section></template>
